import { test, expect } from '@playwright/test';

test.describe('Footer Navigation Links', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should navigate to correct pages when clicking footer links', async ({ page }) => {
    // Verify footer is visible
    const footer = page.getByRole('contentinfo', { name: /footer/i });
    await expect(footer).toBeVisible();

    // Verify footer links container exists
    const footerLinks = page.getByRole('navigation', { name: /footer links/i });
    await expect(footerLinks).toBeVisible();

    // Click 'About Us' link
    const aboutLink = page.getByRole('link', { name: /about us/i });
    await expect(aboutLink).toBeVisible();
    await aboutLink.click();

    // Verify About Us page loaded
    await expect(page).toHaveURL(/.*\/about/);
    const aboutTitle = page.getByRole('heading', { name: /about us/i });
    await expect(aboutTitle).toBeVisible();

    // Click 'Contact' link
    const contactLink = page.getByRole('link', { name: /contact us/i });
    await expect(contactLink).toBeVisible();
    await contactLink.click();

    // Verify Contact page loaded
    await expect(page).toHaveURL(/.*\/contact/);
    const contactTitle = page.getByRole('heading', { name: /contact us/i });
    await expect(contactTitle).toBeVisible();

    // Click 'Privacy Policy' link
    const privacyLink = page.getByRole('link', { name: /privacy policy/i });
    await expect(privacyLink).toBeVisible();
    await privacyLink.click();

    // Verify Privacy Policy page loaded
    await expect(page).toHaveURL(/.*\/privacy-policy/);
    const privacyTitle = page.getByRole('heading', { name: /privacy policy/i });
    await expect(privacyTitle).toBeVisible();
  });

  test('should handle broken footer links gracefully and display error message', async ({ page }) => {
    // Intercept a known broken link
    await page.route('**/broken-link', route => {
      route.abort('failed');
    });

    // Click the broken link
    const brokenLink = page.getByRole('link', { name: /broken link/i });
    await expect(brokenLink).toBeVisible();
    await brokenLink.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/page not found/i);
    await expect(errorMessage).toBeVisible();

    // Verify user is still on the home page (or error page)
    await expect(page).toHaveURL(/.*\/error/);

    // Verify footer is still accessible
    const footer = page.getByRole('contentinfo', { name: /footer/i });
    await expect(footer).toBeVisible();

    // Click a working link to ensure navigation is not blocked
    const homeLink = page.getByRole('link', { name: /home/i });
    await expect(homeLink).toBeVisible();
    await homeLink.click();

    // Verify home page loads
    await expect(page).toHaveURL(/.*\/$/);
    const homeTitle = page.getByRole('heading', { name: /home/i });
    await expect(homeTitle).toBeVisible();
  });
});
